$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$listener = New-Object System.Net.HttpListener
$listener.Prefixes.Add('http://localhost:8000/')
try { $listener.Start(); Start-Process 'http://localhost:8000/'; Write-Host 'Accounts Management is running at http://localhost:8000/'; Write-Host 'Keep this window open. Press Ctrl+C to stop.'; while ($listener.IsListening) { $ctx = $listener.GetContext(); $path = [Uri]::UnescapeDataString($ctx.Request.Url.AbsolutePath.TrimStart('/')); if ([string]::IsNullOrWhiteSpace($path)) { $path = 'index.html' }; $full = [IO.Path]::GetFullPath((Join-Path $root $path)); if (-not $full.StartsWith([IO.Path]::GetFullPath($root), [StringComparison]::OrdinalIgnoreCase) -or -not (Test-Path -LiteralPath $full -PathType Leaf)) { $ctx.Response.StatusCode = 404; $bytes = [Text.Encoding]::UTF8.GetBytes('Not found'); } else { $ext = [IO.Path]::GetExtension($full).ToLowerInvariant(); $ctx.Response.ContentType = switch ($ext) { '.html' {'text/html; charset=utf-8'} '.js' {'application/javascript; charset=utf-8'} '.css' {'text/css; charset=utf-8'} '.json' {'application/json; charset=utf-8'} default {'application/octet-stream'} }; $bytes = [IO.File]::ReadAllBytes($full) }; $ctx.Response.ContentLength64 = $bytes.Length; $ctx.Response.OutputStream.Write($bytes,0,$bytes.Length); $ctx.Response.Close() } } finally { $listener.Stop(); $listener.Close() }
